/**
 * @brief Scripted session with checks; prints the anchored verdict line.
 * @param inject_failure 1 adds a failing check (negative control).
 * @return 0 on TEST PASS, 1 on TEST FAIL.
 */
static int demo_run(int inject_failure)
{
    char help_q[8192];
    const char *verdict_msg;

    plat_init();
    host_capture_clear();
    cli_start();
    demo_check(strstr(host_capture_text(), "RTLNet Ethernet demo -- rtlnet-eth-fw") != NULL, "start-up banner");
    demo_check(strstr(host_capture_text(), "Board TEST, build 1234abcd") != NULL, "banner: board and build");
    demo_check(strstr(host_capture_text(), "rtlnet>") != NULL, "first prompt");

    for (size_t i = 0; i < sizeof(g_steps) / sizeof(g_steps[0]); i++) {
        demo_run_step(&g_steps[i]);
    }

    /* HELP and ? print the same, aligned listing (MenuBuilder section 9). */
    host_capture_clear();
    demo_type("?");
    (void)snprintf(help_q, sizeof(help_q), "%s", strstr(host_capture_text(), "User exec commands:") != NULL ?
                   strstr(host_capture_text(), "User exec commands:") : "");
    demo_type("\r");
    host_capture_clear();
    demo_type("help\r");
    demo_check(help_q[0] != '\0' && strncmp(strstr(host_capture_text(), "User exec commands:") != NULL ?
               strstr(host_capture_text(), "User exec commands:") : "", help_q,
               strlen(help_q) - strlen("rtlnet>")) == 0, "HELP and ? print the same listing");
    demo_check(demo_aligned(help_q), "help listing aligned on one ' - ' column");
    host_capture_clear();
    demo_type("show ?");
    demo_check(demo_aligned(host_capture_text()), "context help aligned on one ' - ' column");
    demo_type("\x03");

    /* Model LED register follows "led 3 on". */
    demo_check((host_model_leds() & 0x08u) != 0u, "LEDS register bit 3 set by led 3 on");

    /* The same firmware with a core present: the probe reports it. */
    host_model_set_core(RTLNET_PLAT_MAC_BASE, RTLNET_ID_MAC);
    host_capture_clear();
    demo_type("show interfaces\r");
    demo_check(strstr(host_capture_text(), "eth0 is down") != NULL &&
               strstr(host_capture_text(), "MAC speed       :") != NULL, "present MAC core reported through its driver");
    demo_check(strstr(host_capture_text(), "not present") == NULL, "present core not reported absent");
    host_model_set_core(RTLNET_PLAT_MAC_BASE, 0u);

    /* The classifier present: boot configuration and counters through the driver. */
    demo_cpupath();

    /* Checksum offload: discovery, change order, receive policy, CLI. */
    demo_offload();

    /* A board that supports only 10 and 100 Mb/s: "speed auto" advertises exactly those two modes, "speed 1000" stays refused. */
    host_model_set_link_caps(ETHS_LINK_10F | ETHS_LINK_100F);
    demo_check(netmgr_adv_supported() == (RTLNET_PHY_ADV_10F | RTLNET_PHY_ADV_100F), "10/100 board: speed auto = 10f and 100f");
    host_model_set_link_caps(ETHS_LINK_10F);
    demo_check(netmgr_adv_supported() == RTLNET_PHY_ADV_10F, "10-only board: speed auto = 10f");
    host_capture_clear();
    demo_type("enable\r");
    demo_type("configure terminal\r");
    demo_type("interface eth0\r");
    demo_type("speed 100\r");
    demo_check(strstr(host_capture_text(), "% This board does not support 100 Mb/s") != NULL, "10-only board refuses speed 100");
    demo_type("end\r");
    host_model_set_link_caps(ETHS_LINK_MASK);
    demo_check(netmgr_adv_supported() == RTLNET_PHY_ADV_FULL, "10/100/1000 board: speed auto = 10f, 100f and 1000f");

    /* Reload restarts the console in user exec mode with default settings. */
    demo_type("enable\r");
    host_capture_clear();
    demo_type("reload\r");
    demo_check(host_reload_count() == 1, "reload called the platform restart");
    demo_check(strstr(host_capture_text(), "Reloading...") != NULL &&
               strstr(host_capture_text(), "RTLNet Ethernet demo -- rtlnet-eth-fw") != NULL, "reload banner");
    demo_check(Menu_GetMode() == MENU_MODE_EXEC, "reload returns to user exec");
    demo_type("enable\r");
    host_capture_clear();
    demo_type("show running-config\r");
    demo_check(strstr(host_capture_text(), " speed auto") != NULL, "reload restores the default configuration");

    /* Negative control: --inject-failure must turn the verdict into TEST FAIL. */
    if (inject_failure) {
        demo_check(0, "INJECT_FAILURE negative control");
    }

    verdict_msg = (g_checks == 0) ? "no checks ran" : g_first_fail;
    for (char *q = g_first_fail; *q != '\0'; q++) {
        if (*q == '\r' || *q == '\n') {
            *q = ' ';
        }
    }
    if (g_fails == 0 && g_checks > 0) {
        printf("\nTEST PASS: menu_demo checks=%d\n", g_checks);
        return 0;
    }
    printf("\nTEST FAIL: menu_demo fails=%d checks=%d first=%s\n", g_fails, g_checks, verdict_msg);
    return 1;
}

/**
 * @brief Harness entry: --demo runs the scripted session (add
 *        --inject-failure for the negative control), otherwise an
 *        interactive session on stdin/stdout until end of input.
 * @param argc Argument count.
 * @param argv Arguments.
 * @return 0 on success (demo: TEST PASS).
 */
int main(int argc, char **argv)
{
    if (argc > 1 && strcmp(argv[1], "--demo") == 0) {
        return demo_run(argc > 2 && strcmp(argv[2], "--inject-failure") == 0);
    }
    plat_init();
    cli_start();
    for (;;) {
        int c = getchar();
        if (c == EOF) {
            break;
        }
        Menu_InputChar(c);
    }
    printf("\n");
    return 0;
}
